const test=require('node:test');
const assert=require('node:assert/strict');
const {execute}=require('../release/service.cjs');
test('reverse awaited rollback, error identities and stop applying',async()=>{
  const events=[],primary=new Error('activate'),undo=new Error('restore');
  const steps=[
    {name:'files',async apply(){events.push('files+');await Promise.resolve();return 0;},
      async rollback(token){assert.equal(token,0);await Promise.resolve();events.push('files-');}},
    {name:'link',async apply(){events.push('link+');return 'old';},
      async rollback(token){assert.equal(token,'old');await Promise.resolve();events.push('link-');throw undo;}},
    {name:'activate',apply(){events.push('activate+');throw primary;},rollback(){assert.fail('failed step rollback');}},
    {name:'later',apply(){assert.fail('later apply');},rollback(){assert.fail('later rollback');}}
  ];
  await assert.rejects(execute(steps),error=>{
    assert.ok(error instanceof AggregateError);
    assert.deepEqual(error.errors,[primary,undo]);
    return true;
  });
  assert.deepEqual(events,['files+','link+','activate+','link-','files-']);
  assert.equal(steps.length,4);
});
test('success, empty and preflight validation',async()=>{
  const events=[];
  assert.deepEqual(await execute([{name:'a',apply:async()=>{events.push('a');return undefined;},rollback(){assert.fail();}},
    {name:'b',apply:()=>{events.push('b');return false;},rollback(){assert.fail();}}]),[undefined,false]);
  assert.deepEqual(events,['a','b']);
  assert.deepEqual(await execute([]),[]);
  const good={name:'same',apply(){assert.fail('preflight must finish first');},rollback(){}};
  for(const bad of [{...good}, {name:'b',apply:3,rollback(){}},{name:'',apply(){},rollback(){}}]) {
    await assert.rejects(execute([good,bad]),TypeError);
  }
});
test('first step failure has no rollback',async()=>{
  const primary=new Error('first');
  await assert.rejects(execute([{name:'a',apply(){throw primary;},rollback(){assert.fail();}}]),error=>{
    assert.ok(error instanceof AggregateError);
    assert.deepEqual(error.errors,[primary]);return true;
  });
});

