exports.validate=steps=>{
  if(!Array.isArray(steps)) throw new TypeError('invalid plan');
  const names=new Set();
  for(const step of steps) {
    if(!step || typeof step.name!=='string' || step.name.length===0 || names.has(step.name) || typeof step.apply!=='function' || typeof step.rollback!=='function') throw new TypeError('invalid step');
    names.add(step.name);
  }
};

