exports.unwind=async function(completed) {
  const errors=[];
  for(let index=completed.length-1;index>=0;index--) {
    const item=completed[index];
    try {await item.step.rollback(item.token);}
    catch(error) {errors.push(error);}
  }
  return errors;
};

